use super::*;
use crate::DomainError;

// Real git 2.56 output, generated by `testdata/file-log.sh` (`sh file-log.sh testdata`) in a
// temporary repo with `GIT_CONFIG_GLOBAL=/dev/null`, fixed authors and dates. The command is
// `git log <FILE_LOG_ARGS> [--follow] -- <path>`. History: add `old.txt`, an unrelated commit,
// edit (with a body), rename to `new.txt`, edits on `side` and `main`, a merge that resolves
// the conflict, then a Latin-1 named file added and removed.

/// `--follow -- new.txt`: merge, two edits, the rename and the commits under the old name.
const FOLLOW: &[u8] = include_bytes!("testdata/file-log-follow.bin");
/// `-- new.txt` without `--follow`: stops at the rename, seen as an addition.
const NO_FOLLOW: &[u8] = include_bytes!("testdata/file-log-nofollow.bin");
/// `-- caf\xe9.txt`: a non-UTF-8 name, added then deleted.
const LATIN1: &[u8] = include_bytes!("testdata/file-log-latin1.bin");
/// A path that never existed: zero bytes.
const EMPTY: &[u8] = include_bytes!("testdata/file-log-empty.bin");

const MERGE: &str = "6e3fced0409379cb380a1c9e8c256a33fce472ed";

fn oid(hex: &str) -> Oid {
    Oid::from_hex(hex.as_bytes()).expect("valid test oid")
}

fn summary(entries: &[FileLogEntry]) -> Vec<(&str, Change, String, Option<String>)> {
    entries
        .iter()
        .map(|e| {
            (
                e.commit.summary.as_str(),
                e.status,
                e.path.to_string(),
                e.old_path.as_ref().map(ToString::to_string),
            )
        })
        .collect()
}

fn reason(input: &[u8]) -> String {
    match parse_file_log(input) {
        Err(DomainError::InvalidGitOutput { command, reason }) => {
            assert_eq!(command, "log");
            reason
        }
        other => panic!("expected an error, got {other:?}"),
    }
}

#[test]
fn follows_the_rename() {
    let entries = parse_file_log(FOLLOW).expect("valid log");
    let new = || "new.txt".to_owned();
    let old = || "old.txt".to_owned();
    assert_eq!(
        summary(&entries),
        [
            ("Merge branch 'side'", Change::Modified, new(), None),
            ("Main edit", Change::Modified, new(), None),
            ("Side edit", Change::Modified, new(), None),
            ("Rename", Change::Renamed, new(), Some(old())),
            ("Edit old", Change::Modified, old(), None),
            ("Add old", Change::Added, old(), None),
        ]
    );
    let merge = &entries[0].commit;
    assert_eq!(merge.id, oid(MERGE));
    assert!(merge.is_merge());
    assert_eq!(merge.body, "# Conflicts:\n#\tnew.txt");
    assert_eq!(entries[4].commit.body, "Body line.");
    assert!(entries[5].commit.parents.is_empty());
    assert_eq!(entries[5].commit.author.offset_min, 120);
}

#[test]
fn without_follow_stops_at_the_rename() {
    let entries = parse_file_log(NO_FOLLOW).expect("valid log");
    let last = entries.last().expect("entries");
    assert_eq!(entries.len(), 4);
    assert_eq!(last.commit.summary, "Rename");
    assert_eq!(last.status, Change::Added);
    assert_eq!(last.old_path, None);
}

#[test]
fn keeps_non_utf8_names() {
    let entries = parse_file_log(LATIN1).expect("valid log");
    let got: Vec<(Change, &[u8])> = entries
        .iter()
        .map(|e| (e.status, e.path.as_bytes()))
        .collect();
    assert_eq!(
        got,
        [
            (Change::Deleted, &b"caf\xe9.txt"[..]),
            (Change::Added, &b"caf\xe9.txt"[..])
        ]
    );
}

#[test]
fn empty_output_gives_no_entries() {
    assert!(EMPTY.is_empty());
    assert_eq!(parse_file_log(EMPTY).expect("valid log"), []);
}

#[test]
fn args_contain_the_log_format() {
    assert!(FILE_LOG_ARGS.starts_with(LOG_ARGS));
    assert!(FILE_LOG_ARGS.contains(&"--diff-merges=first-parent"));
}

/// The bytes of the first commit of [`LATIN1`] with its entry (up to the start of the second
/// commit, whose id appears before only as the parent of the first).
fn first_record() -> &'static [u8] {
    let second = parse_file_log(LATIN1).expect("valid log")[1]
        .commit
        .id
        .to_string();
    let at = LATIN1
        .windows(second.len())
        .rposition(|w| w == second.as_bytes())
        .expect("second commit present");
    &LATIN1[..at]
}

#[test]
fn rejects_malformed_output() {
    assert!(reason(&FOLLOW[..FOLLOW.len() - 1]).contains("does not end with NUL"));
    // A commit without entries (merge without `--diff-merges`).
    let record = first_record();
    assert!(parse_file_log(record).is_ok());
    let newline = record.iter().rposition(|&b| b == b'\n').expect("entries");
    let mut bare = record[..newline].to_vec();
    assert!(reason(&bare).contains("has no `--name-status` entry"));
    // Two entries for one commit.
    bare.extend_from_slice(b"\nM\0a\0M\0b\0");
    assert!(reason(&bare).contains("more than one"));
    // Incomplete rename.
    bare.truncate(newline);
    bare.extend_from_slice(b"\nR100\0a\0");
    assert!(reason(&bare).contains("incomplete"));
    // Unknown status.
    bare.truncate(newline);
    bare.extend_from_slice(b"\nX\0a\0");
    assert!(reason(&bare).contains("unknown status"));
    // Truncated record.
    assert!(reason(b"abc\0").contains("fields instead of"));
}

#[test]
fn serializes_to_json() {
    let entries = parse_file_log(LATIN1).expect("valid log");
    let json = serde_json::to_value(&entries).expect("serializable");
    assert_eq!(json[0]["status"], "Deleted");
    let back: Vec<FileLogEntry> = serde_json::from_value(json).expect("deserializable");
    assert_eq!(back, entries);
}
